#pragma once

#include <stddef.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

// Writes the 32-byte HMAC-SHA256 digest of `data` under `key` into `out`.
void hmac_sha256(const uint8_t *key, size_t keylen, const uint8_t *data,
                  size_t datalen, uint8_t out[32]);

#ifdef __cplusplus
}
#endif

#include "hmac_sha256.h"

#include <string.h>

#include "sha256.h"

void hmac_sha256(const uint8_t *key, size_t keylen, const uint8_t *data,
                  size_t datalen, uint8_t out[32]) {
  uint8_t key_block[64] = {0};

  if (keylen > 64) {
    SHA256_CTX ctx;
    sha256_init(&ctx);
    sha256_update(&ctx, key, keylen);
    sha256_final(&ctx, key_block); // digest is 32 bytes; rest stays zero-padded
  } else {
    memcpy(key_block, key, keylen);
  }

  uint8_t k_ipad[64];
  uint8_t k_opad[64];
  for (int i = 0; i < 64; ++i) {
    k_ipad[i] = key_block[i] ^ 0x36;
    k_opad[i] = key_block[i] ^ 0x5c;
  }

  uint8_t inner_hash[32];
  SHA256_CTX ctx;
  sha256_init(&ctx);
  sha256_update(&ctx, k_ipad, 64);
  sha256_update(&ctx, data, datalen);
  sha256_final(&ctx, inner_hash);

  sha256_init(&ctx);
  sha256_update(&ctx, k_opad, 64);
  sha256_update(&ctx, inner_hash, 32);
  sha256_final(&ctx, out);
}

// Pure AWS Signature Version 4 request signing.
//
// Deliberately free of any networking/Arduino dependency so it can be
// unit-tested on the host (`pio test -e native`) against the published AWS
// SigV4 test vectors, independent of hardware or a live MinIO instance.
// s3_uploader.cpp is the only caller and owns all networking/SD I/O.
#pragma once

#include <stdint.h>

#include <string>
#include <vector>

namespace sigv4 {

struct Header {
  std::string name; // must already be lowercase, no leading/trailing whitespace
  std::string value; // must already be trimmed
};

// Hex-encoded SHA-256 of `data`.
std::string sha256_hex(const std::string &data);

// Builds the canonical request (method\ncanonical_uri\ncanonical_query_string\n
// canonical_headers\nsigned_headers\npayload_hash) per the SigV4 spec.
// `headers` is sorted by name internally; `signed_headers_out` receives the
// semicolon-joined sorted header names used in both the canonical request and
// the final Authorization header.
std::string canonical_request(const std::string &method,
                               const std::string &canonical_uri,
                               const std::string &canonical_query_string,
                               std::vector<Header> headers,
                               const std::string &payload_hash,
                               std::string &signed_headers_out);

// "AWS4-HMAC-SHA256\n<amz_date>\n<date_stamp>/<region>/<service>/aws4_request\n
// <hex sha256 of canonical_request_str>"
std::string string_to_sign(const std::string &amz_date,
                            const std::string &date_stamp,
                            const std::string &region,
                            const std::string &service,
                            const std::string &canonical_request_str);

// Derives the final signing key via the AWS4 HMAC chain:
// secret -> date -> region -> service -> "aws4_request".
void derive_signing_key(const std::string &secret_key,
                         const std::string &date_stamp,
                         const std::string &region, const std::string &service,
                         uint8_t out_key[32]);

// Hex-encoded HMAC-SHA256(signing_key, string_to_sign_str).
std::string sign_hex(const uint8_t signing_key[32],
                      const std::string &string_to_sign_str);

// Assembles the final `Authorization` header value.
std::string authorization_header(const std::string &access_key,
                                  const std::string &date_stamp,
                                  const std::string &region,
                                  const std::string &service,
                                  const std::string &signed_headers,
                                  const std::string &signature_hex);

} // namespace sigv4

#include "sigv4.h"

#include <algorithm>

#include "hmac_sha256.h"
#include "sha256.h"

namespace sigv4 {

namespace {

std::string to_hex(const uint8_t *bytes, size_t len) {
  static const char *digits = "0123456789abcdef";
  std::string out;
  out.resize(len * 2);
  for (size_t i = 0; i < len; ++i) {
    out[i * 2] = digits[bytes[i] >> 4];
    out[i * 2 + 1] = digits[bytes[i] & 0x0f];
  }
  return out;
}

void hmac(const uint8_t *key, size_t keylen, const std::string &data,
          uint8_t out[32]) {
  hmac_sha256(key, keylen, reinterpret_cast<const uint8_t *>(data.data()),
              data.size(), out);
}

} // namespace

std::string sha256_hex(const std::string &data) {
  SHA256_CTX ctx;
  uint8_t hash[32];
  sha256_init(&ctx);
  sha256_update(&ctx, reinterpret_cast<const uint8_t *>(data.data()),
                data.size());
  sha256_final(&ctx, hash);
  return to_hex(hash, 32);
}

std::string canonical_request(const std::string &method,
                               const std::string &canonical_uri,
                               const std::string &canonical_query_string,
                               std::vector<Header> headers,
                               const std::string &payload_hash,
                               std::string &signed_headers_out) {
  std::sort(headers.begin(), headers.end(),
            [](const Header &a, const Header &b) { return a.name < b.name; });

  std::string canonical_headers;
  signed_headers_out.clear();
  for (size_t i = 0; i < headers.size(); ++i) {
    canonical_headers += headers[i].name + ":" + headers[i].value + "\n";
    if (i > 0)
      signed_headers_out += ";";
    signed_headers_out += headers[i].name;
  }

  return method + "\n" + canonical_uri + "\n" + canonical_query_string + "\n" +
         canonical_headers + "\n" + signed_headers_out + "\n" + payload_hash;
}

std::string string_to_sign(const std::string &amz_date,
                            const std::string &date_stamp,
                            const std::string &region,
                            const std::string &service,
                            const std::string &canonical_request_str) {
  const std::string scope =
      date_stamp + "/" + region + "/" + service + "/aws4_request";
  return "AWS4-HMAC-SHA256\n" + amz_date + "\n" + scope + "\n" +
         sha256_hex(canonical_request_str);
}

void derive_signing_key(const std::string &secret_key,
                         const std::string &date_stamp,
                         const std::string &region, const std::string &service,
                         uint8_t out_key[32]) {
  uint8_t k_date[32];
  uint8_t k_region[32];
  uint8_t k_service[32];

  const std::string seed = "AWS4" + secret_key;
  hmac(reinterpret_cast<const uint8_t *>(seed.data()), seed.size(), date_stamp,
       k_date);
  hmac(k_date, 32, region, k_region);
  hmac(k_region, 32, service, k_service);
  hmac(k_service, 32, "aws4_request", out_key);
}

std::string sign_hex(const uint8_t signing_key[32],
                      const std::string &string_to_sign_str) {
  uint8_t signature[32];
  hmac(signing_key, 32, string_to_sign_str, signature);
  return to_hex(signature, 32);
}

std::string authorization_header(const std::string &access_key,
                                  const std::string &date_stamp,
                                  const std::string &region,
                                  const std::string &service,
                                  const std::string &signed_headers,
                                  const std::string &signature_hex) {
  const std::string scope =
      date_stamp + "/" + region + "/" + service + "/aws4_request";
  return "AWS4-HMAC-SHA256 Credential=" + access_key + "/" + scope +
         ", SignedHeaders=" + signed_headers + ", Signature=" + signature_hex;
}

} // namespace sigv4

// Verifies the sigv4 module against AWS's published "get-vanilla" SigV4 test
// vector (aws-sig-v4-test-suite), independently re-derived and cross-checked
// against a from-scratch Python HMAC chain before being hardcoded here.
// Run with: pio test -e native
#include <unity.h>

#include "sigv4.h"

static const char *kAccessKey = "AKIDEXAMPLE";
static const char *kSecretKey = "wJalrXUtnFEMI/K7MDENG+bPxRfiCYEXAMPLEKEY";
static const char *kDateStamp = "20150830";
static const char *kAmzDate = "20150830T123600Z";
static const char *kRegion = "us-east-1";
static const char *kService = "service";

static const char *kExpectedCanonicalRequest =
    "GET\n"
    "/\n"
    "\n"
    "host:example.amazonaws.com\n"
    "x-amz-date:20150830T123600Z\n"
    "\n"
    "host;x-amz-date\n"
    "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";

static const char *kExpectedStringToSign =
    "AWS4-HMAC-SHA256\n"
    "20150830T123600Z\n"
    "20150830/us-east-1/service/aws4_request\n"
    "bb579772317eb040ac9ed261061d46c1f17a8133879d6129b6e1c25292927e63";

static const char *kExpectedSignature =
    "5fa00fa31553b73ebf1942676e86291e8372ff2a2260956d9b8aae1d763fbf31";

static const char *kExpectedAuthorizationHeader =
    "AWS4-HMAC-SHA256 "
    "Credential=AKIDEXAMPLE/20150830/us-east-1/service/aws4_request, "
    "SignedHeaders=host;x-amz-date, "
    "Signature=5fa00fa31553b73ebf1942676e86291e8372ff2a2260956d9b8aae1d763fbf31";

void test_sha256_empty_string(void) {
  TEST_ASSERT_EQUAL_STRING(
      "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
      sigv4::sha256_hex("").c_str());
}

void test_canonical_request_matches_aws_vector(void) {
  std::string signed_headers;
  const std::string payload_hash = sigv4::sha256_hex("");
  const std::string creq = sigv4::canonical_request(
      "GET", "/", "",
      {{"host", "example.amazonaws.com"}, {"x-amz-date", kAmzDate}},
      payload_hash, signed_headers);

  TEST_ASSERT_EQUAL_STRING("host;x-amz-date", signed_headers.c_str());
  TEST_ASSERT_EQUAL_STRING(kExpectedCanonicalRequest, creq.c_str());
}

void test_string_to_sign_matches_aws_vector(void) {
  const std::string sts = sigv4::string_to_sign(
      kAmzDate, kDateStamp, kRegion, kService, kExpectedCanonicalRequest);
  TEST_ASSERT_EQUAL_STRING(kExpectedStringToSign, sts.c_str());
}

void test_full_signature_matches_aws_vector(void) {
  uint8_t signing_key[32];
  sigv4::derive_signing_key(kSecretKey, kDateStamp, kRegion, kService,
                             signing_key);
  const std::string signature =
      sigv4::sign_hex(signing_key, kExpectedStringToSign);
  TEST_ASSERT_EQUAL_STRING(kExpectedSignature, signature.c_str());
}

void test_authorization_header_matches_aws_vector(void) {
  const std::string header = sigv4::authorization_header(
      kAccessKey, kDateStamp, kRegion, kService, "host;x-amz-date",
      kExpectedSignature);
  TEST_ASSERT_EQUAL_STRING(kExpectedAuthorizationHeader, header.c_str());
}

// Headers passed out of order must still sort correctly into the canonical
// form (MinIO PUT requests build {x-amz-date, x-amz-content-sha256, host} in
// whatever order the caller assembles them).
void test_canonical_request_sorts_unordered_headers(void) {
  std::string signed_headers;
  const std::string creq = sigv4::canonical_request(
      "GET", "/", "",
      {{"x-amz-date", kAmzDate}, {"host", "example.amazonaws.com"}},
      sigv4::sha256_hex(""), signed_headers);
  TEST_ASSERT_EQUAL_STRING("host;x-amz-date", signed_headers.c_str());
  TEST_ASSERT_EQUAL_STRING(kExpectedCanonicalRequest, creq.c_str());
}

int main(int argc, char **argv) {
