// PDM microphone capture, the PSRAM pre-trigger ring buffer, and the
// trigger -> snapshot -> post-capture -> atomic-WAV-save sequence.
//
// Ported from data_collection/data_collector.py's save_audio()/ring-buffer
// model: a continuously-overwritten ring buffer holds kPreTriggerSeconds of
// audio; on trigger, its contents are snapshotted and kPostTriggerSeconds
// more are captured directly (the ring buffer is *not* fed during this
// window, matching the Pi's behavior), then the concatenated clip is written
// as one WAV file.
//
// Owned entirely by the Arduino loop()/core-1 task — no locking needed here.
// The only cross-core interaction is the trigger notification consumed from
// mqtt_client via a FreeRTOS task notification (see request_recording()).
#pragma once

namespace audio_capture {

bool begin();

// Call once per loop() iteration. Reads one PDM chunk, feeds the ring buffer
// or an in-progress clip depending on state, and finalizes+saves a clip when
// the post-trigger capture completes.
void loop_tick();

// Called from mqtt_client's on-message callback (a different task/core) when
// a trigger message arrives. Cheap and safe to call from another task: it
// only posts a FreeRTOS task notification to the loop() task, consumed
// non-blockingly by loop_tick(). A trigger arriving while a recording is
// already in progress is simply dropped (notifications coalesce), matching
// the Pi's guard-flag behavior of ignoring concurrent triggers.
void request_recording();

bool is_recording();

} // namespace audio_capture

// NTP wall-clock sync. The XIAO ESP32S3 Sense has no onboard RTC, so local
// time is only meaningful once this has synced at least once after a WiFi
// connection, and needs periodic resync since the internal clock drifts.
#pragma once

#include <ctime>

namespace ntp_time {

// Starts the sync (configTzTime with TZ_STRING); non-blocking, call once
// WiFi is connected. Safe to call again to force a resync.
void sync();

bool is_synced();

// Local time per TZ_STRING. Only meaningful if is_synced() is true.
tm local_now();

// Calls sync() again if kNtpResyncIntervalMs has elapsed since the last
// successful sync. Call periodically from networkTask.
void maybe_resync();

} // namespace ntp_time

#include "ntp_time.h"

#include <Arduino.h>

#include "config.h"

namespace ntp_time {

namespace {
// Any wall-clock time before this is treated as "not yet synced" — an
// unsynced ESP32 reports an epoch near 0 (1970), so this is a cheap,
// reliable-enough heuristic without tracking a separate success flag from
// configTzTime's async callback.
constexpr time_t kMinPlausibleEpoch = 1700000000; // 2023-11-14

uint32_t g_last_sync_attempt_ms = 0;
} // namespace

void sync() {
  configTzTime(TZ_STRING, "pool.ntp.org", "time.nist.gov");
  g_last_sync_attempt_ms = millis();
}

bool is_synced() { return time(nullptr) >= kMinPlausibleEpoch; }

tm local_now() {
  time_t now = time(nullptr);
  tm result{};
  localtime_r(&now, &result);
  return result;
}

void maybe_resync() {
  if (millis() - g_last_sync_attempt_ms >= kNtpResyncIntervalMs) {
    sync();
  }
}

} // namespace ntp_time

#include "audio_capture.h"

#include <Arduino.h>
#include <I2S.h>
#include <esp_heap_caps.h>

#include <cstdio>
#include <string>

#include "config.h"
#include "ntp_time.h"
#include "sd_storage.h"
#include "wav_writer.h"

namespace audio_capture {

namespace {

enum class State { kIdle, kRecording };

TaskHandle_t g_loop_task = nullptr;
State g_state = State::kIdle;

// Pre-trigger ring buffer (PSRAM). Owned exclusively by loop_tick()/core 1.
uint8_t *g_ring_buf = nullptr;
size_t g_ring_write_pos = 0;
size_t g_ring_filled = 0; // caps at kRingBufferBytes once it has wrapped once

// In-progress clip assembly (PSRAM). Sized for pre+post+margin.
uint8_t *g_clip_buf = nullptr;
size_t g_clip_len = 0;
size_t g_clip_target_len = 0;
std::string g_clip_final_path;

uint8_t g_read_chunk[kPdmReadChunkBytes];

void ring_append(const uint8_t *data, size_t len) {
  for (size_t i = 0; i < len; ++i) {
    g_ring_buf[g_ring_write_pos] = data[i];
    g_ring_write_pos = (g_ring_write_pos + 1) % kRingBufferBytes;
  }
  g_ring_filled = min(g_ring_filled + len, kRingBufferBytes);
}

// Copies the ring buffer out in chronological (oldest-to-newest) order.
void ring_snapshot_into(uint8_t *dst) {
  if (g_ring_filled < kRingBufferBytes) {
    // Buffer hasn't wrapped yet: contents from [0, g_ring_filled) are already
    // in chronological order (only reached during the first
    // kPreTriggerSeconds after boot).
    memcpy(dst, g_ring_buf, g_ring_filled);
    return;
  }
  const size_t tail_len = kRingBufferBytes - g_ring_write_pos;
  memcpy(dst, g_ring_buf + g_ring_write_pos, tail_len);
  memcpy(dst + tail_len, g_ring_buf, g_ring_write_pos);
}

std::string make_filename() {
  char name[64];
  if (ntp_time::is_synced()) {
    tm t = ntp_time::local_now();
    std::strftime(name, sizeof(name), "doorbell_manual_%Y%m%d_%H%M%S.wav",
                   &t);
  } else {
    // NTP hasn't synced yet (e.g. a trigger fires seconds after boot) —
    // fall back to a millis()-based name so the recording isn't dropped.
    std::snprintf(name, sizeof(name), "doorbell_manual_boot_%lu.wav",
                  static_cast<unsigned long>(millis()));
  }
  return std::string(kRecordingsDir) + "/" + name;
}

void begin_recording() {
  g_clip_final_path = make_filename();
  g_clip_len = 0;
  g_clip_target_len = kRingBufferBytes; // pre-trigger portion, filled below
  ring_snapshot_into(g_clip_buf);
  g_clip_len = kRingBufferBytes;
  g_clip_target_len =
      kRingBufferBytes +
      static_cast<size_t>(kPostTriggerSeconds * kBytesPerSecond);
  g_state = State::kRecording;
}

void finish_recording() {
  const std::string tmp_path = sd_storage::temp_path_for(g_clip_final_path);

  if (sd_storage::lock(2000)) {
    File f = SD.open(tmp_path.c_str(), FILE_WRITE);
    if (f) {
      auto header = wav_writer::build_header(
          g_clip_len, kSampleRateHz, kBitsPerSample, kChannels);
      f.write(header.data(), header.size());
      f.write(g_clip_buf, g_clip_len);
      f.close();
      sd_storage::commit_temp_file(g_clip_final_path);
    }
    sd_storage::unlock();
  }

  g_state = State::kIdle;
}

} // namespace

bool begin() {
  g_loop_task = xTaskGetCurrentTaskHandle();

  g_ring_buf = static_cast<uint8_t *>(
      heap_caps_malloc(kRingBufferBytes, MALLOC_CAP_SPIRAM));
  g_clip_buf = static_cast<uint8_t *>(
      heap_caps_malloc(kClipBufferBytes, MALLOC_CAP_SPIRAM));
  if (g_ring_buf == nullptr || g_clip_buf == nullptr) {
    // Almost always means board_build.arduino.memory_type isn't configured
    // for PSRAM (qio_opi) — fail loudly rather than let later writes
    // corrupt memory.
    return false;
  }

  I2S.setPinsPdmRx(kPdmClkPin, kPdmDataPin);
  if (!I2S.begin(I2S_MODE_PDM_RX, kSampleRateHz, I2S_DATA_BIT_WIDTH_16BIT,
                 I2S_SLOT_MODE_MONO)) {
    return false;
  }

  return true;
}

void loop_tick() {
  size_t n = I2S.readBytes(reinterpret_cast<char *>(g_read_chunk),
                            sizeof(g_read_chunk));
  if (n == 0) {
    return;
  }

  if (g_state == State::kIdle) {
    ring_append(g_read_chunk, n);

    if (ulTaskNotifyTake(pdTRUE, 0) > 0) {
      begin_recording();
    }
    return;
  }

  // kRecording: append straight into the clip buffer (the ring buffer is
  // intentionally not fed during this window, matching the Pi's behavior of
  // reading post-trigger audio directly rather than through the pre-trigger
  // buffer).
  size_t remaining = g_clip_target_len - g_clip_len;
  size_t to_copy = min(remaining, n);
  memcpy(g_clip_buf + g_clip_len, g_read_chunk, to_copy);
  g_clip_len += to_copy;

  if (g_clip_len >= g_clip_target_len) {
    finish_recording();
  }
}

void request_recording() {
  if (g_loop_task != nullptr) {
    xTaskNotifyGive(g_loop_task);
  }
}

bool is_recording() { return g_state == State::kRecording; }

} // namespace audio_capture

