namespace wifi_manager {

// Starts the (async) connection attempt.
void begin();

bool is_connected();

// Kicks off a reconnect if not currently connected. Call periodically from
// networkTask; cheap no-op when already connected.
void maybe_reconnect();

} // namespace wifi_manager

#include "wifi_manager.h"

#include <Arduino.h>
#include <WiFi.h>

#include "config.h"

namespace wifi_manager {

namespace {
uint32_t g_last_attempt_ms = 0;
constexpr uint32_t kReconnectIntervalMs = 10000;
} // namespace

void begin() {
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  g_last_attempt_ms = millis();
}

bool is_connected() { return WiFi.status() == WL_CONNECTED; }

void maybe_reconnect() {
  if (is_connected()) {
    return;
  }
  if (millis() - g_last_attempt_ms >= kReconnectIntervalMs) {
    WiFi.disconnect();
    WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
    g_last_attempt_ms = millis();
  }
}

} // namespace wifi_manager

// MQTT client: connects, subscribes to MQTT_TRIGGER_TOPIC, and forwards any
// message on it to audio_capture::request_recording() — matching the Pi
// scripts' "any payload triggers a recording" semantics (no payload-value
// matching is required for this build).
#pragma once

namespace mqtt_client {

void begin();

// Services the MQTT client (must be called frequently from networkTask) and
// reconnects if the connection dropped.
void loop_tick();

bool is_connected();

} // namespace mqtt_client

#include "mqtt_client.h"

#include <Arduino.h>
#include <PubSubClient.h>
#include <WiFi.h>

#include "audio_capture.h"
#include "config.h"
#include "wifi_manager.h"

namespace mqtt_client {

namespace {

WiFiClient g_wifi_client;
PubSubClient g_client(g_wifi_client);
uint32_t g_last_reconnect_attempt_ms = 0;
constexpr uint32_t kReconnectIntervalMs = 5000;

void on_message(char *topic, uint8_t *payload, unsigned int length) {
  (void)topic;
  (void)payload;
  (void)length;
  // Any message on the trigger topic fires a recording — matches
  // data_collection/data_collector.py's default (no mqtt_trigger_value set).
  audio_capture::request_recording();
}

bool connect() {
  const char *client_id_suffix = DEVICE_ID;
  String client_id = String("esp32-sense-") + client_id_suffix;

  bool ok;
  if (strlen(MQTT_USERNAME) > 0) {
    ok = g_client.connect(client_id.c_str(), MQTT_USERNAME, MQTT_PASSWORD);
  } else {
    ok = g_client.connect(client_id.c_str());
  }

  if (ok) {
    g_client.subscribe(MQTT_TRIGGER_TOPIC);
  }
  return ok;
}

} // namespace

void begin() {
  g_client.setServer(MQTT_HOST, MQTT_PORT);
  g_client.setCallback(on_message);
}

void loop_tick() {
  if (!wifi_manager::is_connected()) {
    return;
  }

  if (!g_client.connected()) {
    if (millis() - g_last_reconnect_attempt_ms >= kReconnectIntervalMs) {
      g_last_reconnect_attempt_ms = millis();
      connect();
    }
    return;
  }

  g_client.loop();
}

bool is_connected() { return g_client.connected(); }

} // namespace mqtt_client

