// SigV4-signed single PUT of one local file to the MinIO bucket. Streams the
// file from SD rather than loading it fully into RAM; uses
// x-amz-content-sha256: UNSIGNED-PAYLOAD so the ~288KB clip isn't hashed
// separately from being streamed (avoids reading it from SD twice).
#pragma once

#include <string>

namespace s3_uploader {

// `local_path` is an SD path (e.g. "/recordings/doorbell_manual_...wav").
// Uploads to MINIO_BUCKET at key "<kS3KeyPrefix>/<DEVICE_ID>/<basename>".
// Caller must hold the SD mutex for the duration of this call (it opens and
// reads local_path).
bool upload_file(const std::string &local_path);

} // namespace s3_uploader

#include "s3_uploader.h"

#include <FS.h>
#include <HTTPClient.h>
#include <SD.h>
#include <WiFi.h>

#include <ctime>

#include "config.h"
#include "sigv4.h"

namespace s3_uploader {

namespace {

std::string basename_of(const std::string &path) {
  size_t slash = path.find_last_of('/');
  return slash == std::string::npos ? path : path.substr(slash + 1);
}

// Percent-encodes everything except unreserved characters (RFC 3986:
// A-Z a-z 0-9 - _ . ~); '/' is preserved as a path separator when
// `preserve_slash` is set, matching SigV4's canonical-URI encoding rules.
std::string uri_encode(const std::string &s, bool preserve_slash) {
  static const char *hex = "0123456789ABCDEF";
  std::string out;
  for (unsigned char c : s) {
    bool unreserved = (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
                       (c >= '0' && c <= '9') || c == '-' || c == '_' ||
                       c == '.' || c == '~';
    if (unreserved || (preserve_slash && c == '/')) {
      out += static_cast<char>(c);
    } else {
      out += '%';
      out += hex[c >> 4];
      out += hex[c & 0x0f];
    }
  }
  return out;
}

// e.g. "20260803T030000Z" / "20260803" — both in UTC, per the SigV4 spec
// (NTP-synced system time is UTC internally regardless of TZ_STRING).
void utc_amz_date(std::string &amz_date_out, std::string &date_stamp_out) {
  time_t now = time(nullptr);
  tm utc{};
  gmtime_r(&now, &utc);
  char amz[17];
  char stamp[9];
  std::strftime(amz, sizeof(amz), "%Y%m%dT%H%M%SZ", &utc);
  std::strftime(stamp, sizeof(stamp), "%Y%m%d", &utc);
  amz_date_out = amz;
  date_stamp_out = stamp;
}

} // namespace

bool upload_file(const std::string &local_path) {
  File f = SD.open(local_path.c_str(), FILE_READ);
  if (!f) {
    return false;
  }
  const size_t file_size = f.size();

  const std::string key = std::string(kS3KeyPrefix) + "/" + DEVICE_ID + "/" +
                           basename_of(local_path);
  const std::string canonical_uri = "/" + uri_encode(MINIO_BUCKET, false) +
                                     "/" + uri_encode(key, true);

  std::string amz_date, date_stamp;
  utc_amz_date(amz_date, date_stamp);

  const std::string payload_hash = "UNSIGNED-PAYLOAD";
  std::string signed_headers;
  const std::string creq = sigv4::canonical_request(
      "PUT", canonical_uri, "",
      {
          {"host", MINIO_ENDPOINT},
          {"x-amz-content-sha256", payload_hash},
          {"x-amz-date", amz_date},
      },
      payload_hash, signed_headers);

  const std::string sts = sigv4::string_to_sign(
      amz_date, date_stamp, MINIO_REGION, kS3Service, creq);

  uint8_t signing_key[32];
  sigv4::derive_signing_key(MINIO_SECRET_KEY, date_stamp, MINIO_REGION,
                             kS3Service, signing_key);
  const std::string signature = sigv4::sign_hex(signing_key, sts);

  const std::string authorization = sigv4::authorization_header(
      MINIO_ACCESS_KEY, date_stamp, MINIO_REGION, kS3Service, signed_headers,
      signature);

  const std::string url =
      std::string("http://") + MINIO_ENDPOINT + canonical_uri;

  WiFiClient client;
  HTTPClient http;
  http.begin(client, url.c_str());
  http.addHeader("x-amz-date", amz_date.c_str());
  http.addHeader("x-amz-content-sha256", payload_hash.c_str());
  http.addHeader("Authorization", authorization.c_str());

  int status = http.sendRequest("PUT", &f, file_size);
  http.end();
  f.close();

  return status >= 200 && status < 300;
}

} // namespace s3_uploader

// Once-daily upload of everything on the SD card to MinIO. Polled from
// networkTask; the SD directory itself is the handoff from audio_capture —
// no "file ready" signal is needed, a daily scan is sufficient.
#pragma once

namespace upload_scheduler {

void begin();

// Call periodically (e.g. every kSchedulerPollIntervalMs) from networkTask.
// Fires run_upload_pass() once per day at kUploadHour local time, plus one
// pass right after the first successful NTP sync (closes the gap where a
// reboot near the upload hour would otherwise wait a full day).
void tick();

} // namespace upload_scheduler

#include "upload_scheduler.h"

#include "config.h"
#include "ntp_time.h"
#include "s3_uploader.h"
#include "sd_storage.h"

namespace upload_scheduler {

namespace {
bool g_uploaded_today = false;
bool g_boot_catchup_done = false;
} // namespace

void begin() {
  g_uploaded_today = false;
  g_boot_catchup_done = false;
}

namespace {

void run_upload_pass() {
  if (!sd_storage::lock()) {
    return;
  }

  for (const auto &path : sd_storage::list_recordings()) {
    if (s3_uploader::upload_file(path)) {
      sd_storage::remove_file(path);
    }
    // On failure, leave the file in place — retried on the next pass.
  }

  sd_storage::unlock();
}

} // namespace

void tick() {
  if (!ntp_time::is_synced()) {
    return;
  }

  if (!g_boot_catchup_done) {
    g_boot_catchup_done = true;
    run_upload_pass(); // no-op if nothing to upload
  }

  tm t = ntp_time::local_now();
  if (t.tm_hour == kUploadHour) {
    if (!g_uploaded_today) {
      run_upload_pass();
      g_uploaded_today = true;
    }
  } else {
    g_uploaded_today = false; // re-arm once we leave the upload hour
  }
}

} // namespace upload_scheduler

// XIAO ESP32S3 Sense doorbell recorder.
//
// Scope: (1) MQTT-triggered recording to SD, (2) once-daily upload of the SD
// card's contents to MinIO. No cross-correlation detection, no on-device ML,
// no camera use — see firmware/esp32-sense/README.md and the project plan
// this was built from.
//
// Concurrency: Arduino's loop() already runs as its own FreeRTOS task
// (pinned to core 1 by default) — that's where audio_capture lives, so it
// spawns no task of its own. One extra task, networkTask (core 0), services
// WiFi/MQTT and the daily upload scheduler.
#include <Arduino.h>

#include "audio_capture.h"
#include "mqtt_client.h"
#include "ntp_time.h"
#include "sd_storage.h"
#include "upload_scheduler.h"
#include "wifi_manager.h"

namespace {

void network_task(void *) {
  wifi_manager::begin();
  mqtt_client::begin();
  upload_scheduler::begin();

  bool ntp_started = false;

  for (;;) {
    wifi_manager::maybe_reconnect();

    if (wifi_manager::is_connected()) {
      if (!ntp_started) {
        ntp_time::sync();
        ntp_started = true;
      } else {
        ntp_time::maybe_resync();
      }

      mqtt_client::loop_tick();
      upload_scheduler::tick();
    }

    vTaskDelay(pdMS_TO_TICKS(100));
  }
}

} // namespace

void setup() {
  Serial.begin(115200);

  if (!sd_storage::begin()) {
    Serial.println("FATAL: SD card init failed");
    while (true) {
      delay(1000);
    }
  }

  if (!audio_capture::begin()) {
    Serial.println(
        "FATAL: audio_capture init failed (PSRAM or I2S/PDM mic)");
    while (true) {
      delay(1000);
    }
  }

  // Core 0 for networking, matching the design's split from Arduino's
  // loop()/core 1 running the audio capture path.
  xTaskCreatePinnedToCore(network_task, "networkTask", 8192, nullptr, 1,
                          nullptr, 0);

  Serial.println("Doorbell recorder ready.");
}

void loop() { audio_capture::loop_tick(); }

