9	  uint8_t key_block[64] = {0};
10	
11	  if (keylen > 64) {
12	    SHA256_CTX ctx;
13	    sha256_init(&ctx);
14	    sha256_update(&ctx, key, keylen);
15	    sha256_final(&ctx, key_block); // digest is 32 bytes; rest stays zero-padded
16	  } else {
17	    memcpy(key_block, key, keylen);
18	  }
19	
20	  uint8_t k_ipad[64];
21	  uint8_t k_opad[64];
22	  for (int i = 0; i < 64; ++i) {
23	    k_ipad[i] = key_block[i] ^ 0x36;
24	    k_opad[i] = key_block[i] ^ 0x5c;
25	  }
26	
27	  uint8_t inner_hash[32];
28	  SHA256_CTX ctx;
29	  sha256_init(&ctx);
30	  sha256_update(&ctx, k_ipad, 64);
31	  sha256_update(&ctx, data, datalen);
32	  sha256_final(&ctx, inner_hash);
33	
34	  sha256_init(&ctx);
35	  sha256_update(&ctx, k_opad, 64);
36	  sha256_update(&ctx, inner_hash, 32);
37	  sha256_final(&ctx, out);
38	}
